def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(kwargs.items()))
            else:
                key = (args, tuple(kwargs.values()))
            if key in cache:
                return cache[key]
            else:
                value = func(*args, **kwargs)
                cache[key] = value
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return value
        return wrapper
    return decorator
