def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        use_count = {}

        def wrapper(*args, **kwargs):
            if typed:
                key = args[0]
            else:
                key = make_key(args, kwargs, typed=typed)
            if key in cache:
                use_count[key] += 1
                wrapper.hits += 1
                return cache[key]
            else:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    for k, v in sorted(use_count.items(), key=lambda x: x[1]):
                        if k not in cache:
                            continue
                        use_count.pop(k)
                        cache.pop(k)
                        break
                use_count[key] = 1
                cache[key] = result
                wrapper.misses += 1
                return result

        def clear():
            cache.clear()
            use_count.clear()
            wrapper.hits = 0
            wrapper.misses = 0

        wrapper.hits = 0
        wrapper.misses = 0
        wrapper.clear = clear
        return wrapper

    return decorator
