def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        try:
            spec_version = inventory['type']
        except KeyError:
            spec_version = self.spec_version
        if not isinstance(spec_version, str):
            raise SchemaFormatException("Invalid specification version")
        if spec_version not in self.supported_versions:
            raise SchemaFormatException("Unsupported specification version")
    else:
        spec_version = self.spec_version

    # Validate the inventory against the schema
    try:
        self.schema.validate(inventory)
    except SchemaError as e:
        raise SchemaFormatException("Invalid inventory") from e

    # Validate the inventory against the specification
    try:
        self.specification.validate(inventory, spec_version)
    except SpecificationError as e:
        raise SchemaFormatException("Invalid inventory") from e

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    for manifest_file in manifest_files:
        if manifest_file.digest not in digests_used:
            raise ValueError(f"Digest {manifest_file.digest} is not present in the digests used.")
        if manifest_file.digest not in self.digests:
            raise ValueError(f"Digest {manifest_file.digest} is not present in the digests.")

