def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for content_file in inventory.get_content_files(version):
        logical_path = content_file.logical_path
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(content_file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for algorithm, values in fixity.items():
        if not isinstance(values, dict):
            raise ValueError("Fixity values must be a dictionary")

        for file_path, checksum in values.items():
            if file_path not in manifest_files:
                raise ValueError(f"File {file_path} not found in manifest")

            if not isinstance(checksum, str):
                raise ValueError(f"Checksum for {file_path} must be a string")

            if not re.match(r"^[a-fA-F0-9]{64}$", checksum):
                raise ValueError(f"Invalid checksum for {file_path}: {checksum}")

    return True

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [path]
    files = []
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            files.append(os.path.join(root, filename))
    return files

