def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not pieces:
        return ""
    if style == "semver":
        return ".".join(str(p) for p in pieces)
    elif style == "pep440":
        return ".".join(str(p) for p in pieces[:2]) + "-" + pieces[2]
    else:
        raise ValueError("unknown style: %s" % style)
