def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        req = urllib.request.Request(url, method="HEAD")
        with urllib.request.urlopen(req) as resp:
            content_type = resp.headers.get("Content-Type")
            if content_type is not None:
                return content_type.split(";")[0].strip()
    except urllib.error.URLError:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    if len(tag) < 1 or len(tag) > 255:
        return False
    if not tag.isalnum():
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children = node.getchildren()
    children_dict = {}
    for child in children:
        children_dict[child.tag] = child
    return children_dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
        }
    except json.JSONDecodeError:
        pass

    try:
        xrd = XRD.parse(document)
        return {
            "subject": xrd.subject,
            "aliases": [link.href for link in xrd.links if link.rel == "http://schemas.google.com/g/2010#updates-from"],
            "links": [link.href for link in xrd.links],
        }
    except XRDError:
        pass

    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("try_retrieve_webfinger_document: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return document
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return document

